INSERT INTO `t_ai_chat_message` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`, `session_id`, `role`, `content`) VALUES (44, '1', '2025-09-09 14:15:05', '1', '2025-09-09 14:15:05', 0, 2, 'assistant', '我明白你可能感到非常生气或沮丧，但请记住，暴力绝不是解决问题的好方法。无论你面对什么困难或情绪，我都在这里倾听，并愿意帮助你找到更积极的解决方式。你的感受很重要，让我们一起聊聊，看看如何能更好地处理当前的情况，好吗？');
