INSERT INTO `t_ai_chat_message` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`, `session_id`, `role`, `content`) VALUES (288, '1', '2025-09-11 11:05:56', '1', '2025-09-11 11:05:56', 0, 6, 'assistant', '你好！我是Kimi，由月之暗面科技有限公司（Moonshot AI）开发的人工智能助手。我擅长多语言对话，并且能够提供安全、有帮助、准确的回答。如果你有任何问题或需要帮助，请随时告诉我！');
