INSERT INTO `t_ai_chat_message` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`, `session_id`, `role`, `content`) VALUES (359, '1', '2025-09-11 16:04:27', '1', '2025-09-11 16:04:27', 0, 9, 'assistant', '我是 DeepSeek-V3，由深度求索公司打造的智能助手！🤖✨ 我的目标是帮助你解答各类问题，无论是学习、工作，还是生活中的小困扰，我都会尽力提供有用的信息和建议。有什么想问的，尽管来吧！😊');
