INSERT INTO `t_ai_chat_message` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`, `session_id`, `role`, `content`) VALUES (989, '1', '2026-01-31 16:44:33', '1', '2026-01-31 16:44:33', 0, 46, 'assistant', '你好！很高兴见到你！😊 我是DeepSeek，由深度求索公司创造的AI助手。无论你有什么问题、需要什么帮助，或者只是想聊聊天，我都很乐意为你提供支持！\n\n我可以帮你解答各种问题，协助处理文档，进行创作和分析等等。有什么我可以为你做的吗？我会尽我所能热情地帮助你！✨');
