INSERT INTO `t_ai_chat_message` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`, `session_id`, `role`, `content`) VALUES (992, '1', '2026-02-07 23:45:29', '1', '2026-02-07 23:45:29', 0, 46, 'user', '你是谁啊');
INSERT INTO `t_ai_chat_message` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`, `session_id`, `role`, `content`) VALUES (993, '1', '2026-02-07 23:45:34', '1', '2026-02-07 23:45:34', 0, 46, 'assistant', '你好！我是DeepSeek，由深度求索公司创造的AI助手！😊\n\n我是一个纯文本模型，可以帮你解答各种问题、进行对话交流、协助处理文档等等。虽然我不支持多模态识别，但我可以处理你上传的图像、txt、pdf、ppt、word、excel等文件，从中读取文字信息来帮助你。\n\n我的一些特点：\n- 完全免费使用，没有收费计划\n- 支持128K上下文长度\n- 可以联网搜索（需要你手动点开联网搜索按键）\n- 有官方App可以下载\n- 知识截止到2024年7月\n\n有什么我可以帮助你的吗？无论是学习、工作还是日常问题，我都很乐意为你提供帮助！✨');
